const input = $input.first().json;
const headers = input.headers ?? {};
const query = input.query ?? {};
const body = input.body ?? {};
const normalizedHeaders = Object.fromEntries(Object.entries(headers).map(([key,value])=>[key.toLowerCase(),value]));
const scanId = body.scanId ?? query.scanId;
const imageUrl = body.imageUrl ?? query.imageUrl;
const contentType = String(normalizedHeaders['content-type'] ?? '').toLowerCase();
if (!scanId || typeof scanId !== 'string') throw new Error('Missing or invalid scanId.');
if (!imageUrl || typeof imageUrl !== 'string') throw new Error('Missing or invalid imageUrl.');
if (input.method === 'POST' && contentType && !contentType.includes('application/json')) throw new Error('POST requests must use Content-Type: application/json.');
return [{json:{valid:true,request:{method:input.method,scanId,imageUrl,headers:normalizedHeaders},integration:{ai_model_configured:false}}}];

const rows = $input.all().flatMap(({ json }) => {
  if (Array.isArray(json)) return json;
  if (Array.isArray(json.data)) return json.data;
  return json && Object.keys(json).length ? [json] : [];
});
return [{ json: { items: rows, count: rows.length } }];

const responses = $input.all();
return responses.map((item, index) => {
  const response = item.json;
  const decision = $('Route AI Decision').itemMatching(index).json;
  const statusCode = Number(response.statusCode ?? response.status) || null;
  const body = response.body ?? {};
  const success = statusCode === 200 && !response.error && body.success !== false && String(body.status ?? '').toLowerCase() !== 'error';
  return { json: {
    event: success ? 'ecoloop_discount_applied' : 'ecoloop_discount_failed',
    success,
    action: 'discount',
    processing_status: success ? 'success' : 'failed',
    http_status: statusCode,
    product_id: decision.product_id,
    discount_percentage: decision.discount_percentage,
    reason: decision.reasoning,
    api_message: body.message ?? null,
    error: success ? null : response.error?.message ?? body.message ?? 'Discount callback did not return HTTP 200.',
    logged_at: new Date().toISOString(),
  } };
});

const reservations = $input.all();
return reservations.map((item, index) => {
  const response = item.json;
  const statusCode = Number(response.statusCode ?? response.status) || null;
  const body = response.body ?? {};
  const reservationOk = statusCode !== null && statusCode >= 200 && statusCode < 300 && !response.error && body.success !== false && String(body.status ?? '').toLowerCase() !== 'error';
  const decision = $('Route AI Decision').itemMatching(index).json;
  const partnerId = decision.recommended_partner_id || 1;
  const productName = decision.product_name ?? 'food item';
  const quantity = decision.quantity ?? 'unspecified';
  const reason = decision.reasoning ?? 'No reason provided';
  return { json: {
    product_id: decision.product_id,
    product_name: productName,
    quantity,
    partner_id: partnerId,
    action: 'donate',
    reasoning: reason,
    reservation_ok: reservationOk,
    reservation_http_status: statusCode,
    reservation_error: reservationOk ? null : response.error?.message ?? body.message ?? 'Donation reservation did not return a successful response.',
    reservation_api_message: body.message ?? null,
    message: `Urgent Food Rescue Alert: ${quantity} units of ${productName} are reserved for donation. Reason: ${reason}`,
  } };
});

const responses = $input.all();
return responses.map((item, index) => {
  const payload = $('Prepare Partner Alert').itemMatching(index).json;
  return { json: {
    event: 'partner_alert_dispatched',
    success: true,
    action: 'donate',
    processing_status: 'success',
    http_status: Number(item.json.statusCode),
    product_id: payload.product_id,
    partner_id: payload.partner_id,
    notification_payload: { partner_id: payload.partner_id, message: payload.message },
    logged_at: new Date().toISOString(),
  } };
});

const responses = $input.all();
return responses.map((item, index) => {
  const payload = $('Prepare Partner Alert').itemMatching(index).json;
  return { json: {
    event: 'partner_alert_failed',
    success: false,
    action: 'donate',
    processing_status: 'failed',
    http_status: Number(item.json.statusCode ?? item.json.status) || null,
    product_id: payload.product_id,
    partner_id: payload.partner_id,
    notification_payload: { partner_id: payload.partner_id, message: payload.message },
    error: item.json.error?.message ?? item.json.body?.message ?? 'Notification returned a non-2xx response.',
    logged_at: new Date().toISOString(),
  } };
});

const items = $input.all();
return items.map(item => ({ json: {
  event: 'donation_reservation_failed',
  success: false,
  action: 'donate',
  processing_status: 'failed',
  product_id: item.json.product_id,
  partner_id: item.json.partner_id,
  http_status: item.json.reservation_http_status,
  error: item.json.reservation_error,
  logged_at: new Date().toISOString(),
} }));

const eligible = $input.all().map(item => item.json).filter(item => ['discount', 'donate', 'none'].includes(item.action));
const count = action => eligible.filter(item => item.action === action).length;
const totalFailed = eligible.filter(item => item.processing_status === 'failed').length;
return [{ json: {
  execution_time: new Date().toISOString(),
  total_processed: eligible.length,
  total_discounted: count('discount'),
  total_donated: count('donate'),
  total_skipped: count('none'),
  total_failed: totalFailed,
  status: 'success',
} }];

const body = $input.first().json.body ?? {};
const id = body.product_id;
if (id === undefined || id === null || !/^\d+$/.test(String(id))) throw new Error('Provide a positive integer product_id in the JSON body.');
return [{json:{product_id:Number(id)}}];

const item = $input.first().json;
const payload = item.body ?? item;
const product = payload.data ?? payload.product ?? payload;
const id = product.product_id ?? product.id ?? $('Validate Demo Request').first().json.product_id;
if (id === undefined || id === null) throw new Error('Laravel product response is missing an id.');
return [{json:{product_id:id, name:product.name ?? product.product_name ?? '', product_name:product.product_name ?? product.name ?? '', expiration_date:product.expiration_date ?? null, quantity:product.quantity ?? null, original_price:product.original_price ?? product.price ?? null, recommended_partner_id:product.recommended_partner_id ?? null}}];

const response = $input.first().json;
const decision = $('Route Live Demo Decision').item.json;
const isNoAction = decision.action === 'none';
const status = Number(response.statusCode ?? response.status) || null;
const body = response.body ?? {};
const apiOk = isNoAction || (status !== null && status >= 200 && status < 300 && !response.error && body.success !== false && String(body.status ?? '').toLowerCase() !== 'error');
return [{json:{success:apiOk, product_id:decision.product_id, action_taken:decision.action, reasoning:decision.reasoning, timestamp:new Date().toISOString(), total_processed:1, total_discounted:decision.action === 'discount' ? 1 : 0, total_donated:decision.action === 'donate' ? 1 : 0, total_skipped:decision.action === 'none' ? 1 : 0, status:apiOk ? 'success' : 'failed'}}];

const items = $input.all();
return items.map(({json}) => {
  const productId = json.product_id ?? json.id;
  if (productId === undefined || productId === null) throw new Error('Product is missing an id.');
  return {json:{...json, product_id:productId, product_name:json.product_name ?? json.name ?? null, action:'none', discount_percentage:0, recommended_partner_id:null, reasoning:'Model AI belum dikonfigurasi. Tidak ada perubahan stok atau harga.', ai_valid:false, decision_source:'model_pending'}};
});

const product = $input.first().json;
if (product.product_id === undefined || product.product_id === null) throw new Error('Product is missing an id.');
return [{json:{...product, action:'none', discount_percentage:0, recommended_partner_id:null, reasoning:'Model AI belum dikonfigurasi. Tidak ada perubahan stok atau harga.', ai_valid:false, decision_source:'model_pending'}}];
